const topDiffs = pickTop2ByPointForm(topTeam.diffStarters);

if (topDiffs.length === 1) {
  return renderTemplate(template.single, {
    team: topTeam.name,
    gw,
    player1: topDiffs[0].name,
    pct1: topDiffs[0].ownershipPct,
  });
}
return renderTemplate(template.multi, {
