    team_chip: chipTeam.name,
    chip: chipName,
    target_clause: isLeaderChip ? 'memperlebar' : 'memangkas',
    margin,
    team_rival: rivalTeam.name,
  });
}

const capLeader = getTeamCaptain(leader.id, gw);
